<?php
class LaporanController{
 function index(){
  require_admin();$db=Database::connect();$month=(int)($_GET['month']??date('n'));$year=(int)($_GET['year']??date('Y'));$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-d',strtotime($start.' +1 month'));$params=[$start,$end];
  $s=$db->prepare('SELECT COUNT(*) transaksi,COALESCE(SUM(total),0) pendapatan,COALESCE(SUM((SELECT COALESCE(SUM(jumlah),0) FROM detail_transaksi d WHERE d.transaksi_id=t.id)),0) produk_terjual FROM transaksi t WHERE tanggal>=? AND tanggal<?');$s->execute($params);$summary=$s->fetch();$summary['rata_rata']=$summary['transaksi']?(float)$summary['pendapatan']/$summary['transaksi']:0;
  $s=$db->prepare('SELECT t.id,t.tanggal,t.total,u.nama kasir,COALESCE(p.nama,"Non-member") pelanggan,t.payment_method FROM transaksi t JOIN users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id=t.pelanggan_id WHERE t.tanggal>=? AND t.tanggal<? ORDER BY t.tanggal DESC');$s->execute($params);$transactions=$s->fetchAll();
  $s=$db->prepare('SELECT p.nama,SUM(d.jumlah) jumlah,SUM(d.subtotal) pendapatan FROM detail_transaksi d JOIN produk p ON p.id=d.produk_id JOIN transaksi t ON t.id=d.transaksi_id WHERE t.tanggal>=? AND t.tanggal<? GROUP BY d.produk_id,p.nama ORDER BY jumlah DESC LIMIT 5');$s->execute($params);$topProducts=$s->fetchAll();
  $stock=$db->query('SELECT COUNT(*) jenis,COALESCE(SUM(stok),0) unit,COALESCE(SUM(stok*harga),0) nilai FROM produk')->fetch();
  $lowStock=$db->query('SELECT nama,stok,harga FROM produk WHERE stok<=5 ORDER BY stok ASC,nama ASC')->fetchAll();
  $s=$db->prepare('SELECT payment_method,COUNT(*) transaksi,COALESCE(SUM(total),0) total FROM transaksi WHERE tanggal>=? AND tanggal<? GROUP BY payment_method ORDER BY total DESC');$s->execute($params);$payments=$s->fetchAll();
  $s=$db->prepare('SELECT k.nama kategori,SUM(d.jumlah) jumlah,SUM(d.subtotal) total FROM detail_transaksi d JOIN produk p ON p.id=d.produk_id LEFT JOIN kategori k ON k.id=p.kategori_id JOIN transaksi t ON t.id=d.transaksi_id WHERE t.tanggal>=? AND t.tanggal<? GROUP BY p.kategori_id,k.nama ORDER BY total DESC');$s->execute($params);$categories=$s->fetchAll();
  $pageTitle='Laporan Penjualan';require __DIR__.'/../views/laporan/index.php';
 }
 function print(){require_admin();$db=Database::connect();$month=(int)($_GET['month']??date('n'));$year=(int)($_GET['year']??date('Y'));$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-d',strtotime($start.' +1 month'));$params=[$start,$end];$s=$db->prepare('SELECT COUNT(*) transaksi,COALESCE(SUM(total),0) pendapatan,COALESCE(SUM((SELECT COALESCE(SUM(jumlah),0) FROM detail_transaksi d WHERE d.transaksi_id=t.id)),0) produk_terjual FROM transaksi t WHERE tanggal>=? AND tanggal<?');$s->execute($params);$summary=$s->fetch();$summary['rata_rata']=$summary['transaksi']?(float)$summary['pendapatan']/$summary['transaksi']:0;$s=$db->prepare('SELECT t.id,t.tanggal,t.total,u.nama kasir,COALESCE(p.nama,"Non-member") pelanggan,t.payment_method FROM transaksi t JOIN users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id=t.pelanggan_id WHERE t.tanggal>=? AND t.tanggal<? ORDER BY t.tanggal ASC');$s->execute($params);$transactions=$s->fetchAll();$s=$db->prepare('SELECT p.nama,SUM(d.jumlah) jumlah,SUM(d.subtotal) pendapatan FROM detail_transaksi d JOIN produk p ON p.id=d.produk_id JOIN transaksi t ON t.id=d.transaksi_id WHERE t.tanggal>=? AND t.tanggal<? GROUP BY d.produk_id,p.nama ORDER BY jumlah DESC');$s->execute($params);$topProducts=$s->fetchAll();$stock=$db->query('SELECT COUNT(*) jenis,COALESCE(SUM(stok),0) unit,COALESCE(SUM(stok*harga),0) nilai FROM produk')->fetch();$lowStock=$db->query('SELECT nama,stok,harga FROM produk WHERE stok<=5 ORDER BY stok ASC,nama ASC')->fetchAll();$pageTitle='Laporan Bulanan';require __DIR__.'/../views/laporan/print.php';
 }
}
